use std::collections::HashMap;
use std::io::{self, Write};
use std::process::ExitCode;

const TOP: usize = 10;

fn main() -> ExitCode {
    let Some(path) = std::env::args_os().nth(1) else {
        eprintln!("usage: word-frequency FILE");
        return ExitCode::FAILURE;
    };

    let data = match std::fs::read(&path) {
        Ok(data) => data,
        Err(err) => {
            eprintln!("word-frequency: {}: {err}", path.to_string_lossy());
            return ExitCode::FAILURE;
        }
    };

    let mut counts: HashMap<Vec<u8>, u64> = HashMap::new();
    for word in data
        .split(|byte| !byte.is_ascii_alphanumeric())
        .filter(|word| !word.is_empty())
    {
        *counts.entry(word.to_ascii_lowercase()).or_insert(0) += 1;
    }

    let mut entries: Vec<(Vec<u8>, u64)> = counts.into_iter().collect();
    entries.sort_unstable_by(|(word_a, count_a), (word_b, count_b)| {
        count_b.cmp(count_a).then_with(|| word_a.cmp(word_b))
    });
    entries.truncate(TOP);

    let mut out = Vec::new();
    for (word, count) in &entries {
        out.extend_from_slice(word);
        out.extend_from_slice(format!(" {count}\n").as_bytes());
    }

    let mut stdout = io::stdout().lock();
    if let Err(err) = stdout.write_all(&out).and_then(|()| stdout.flush()) {
        eprintln!("word-frequency: write failed: {err}");
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}

